var COM = {"0": "<p>Certo. Redação da LC 227/2026.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "1": "<p>Errado. Fica no nível fixado para 2033.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "2": "<p>Certo. Parágrafo único, I.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "3": "<p>Certo. Art. 473, § 1º, II, a.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "4": "<p>Errado. Só a CBS é zerada; a alíquota distrital absorve a soma.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "5": "<p>Certo. Art. 473, § 3º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "6": "<p>Certo. Art. 473, caput.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "7": "<p>Certo. Art. 474, I e IV.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "8": "<p>Errado. Lista apenas 2029 a 2032.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "9": "<p>Certo. Art. 475, II e III.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "10": "<p>Certo. Art. 475, § 3º, I.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "11": "<p>Errado. Até meio salário-mínimo.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "12": "<p>Certo. Art. 475, § 1º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "13": "<p>Certo. Art. 475, § 9º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "14": "<p>Errado. O gatilho é soma superior a 26,5%.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "15": "<p>Certo. Art. 475, § 12, I.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "16": "<p>Certo. Art. 475, § 13.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "17": "<p>Errado. Art. 476: Poder Executivo da União.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "18": "<p>Certo. Art. 476, § 1º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "19": "<p>Certo. Art. 475, § 7º (LC 227/2026).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "20": "<p>Certo. Art. 477, § 1º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "21": "<p>Certo. Art. 477, § 2º, I.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "22": "<p>Errado. É no segundo mês subsequente.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "23": "<p>Certo. Art. 478, II.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "24": "<p>Certo. Art. 479, § 1º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "25": "<p>Errado. Pelo TCU (art. 478, § 3º).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "26": "<p>Certo. Art. 480, caput.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "27": "<p>Errado. Art. 480, § 1º: sem vinculação, tutela ou subordinação.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "28": "<p>Certo. Art. 480, § 2º.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "29": "<p>Certo. Art. 481.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "30": "<p>Errado. Os 14 da alínea a têm voto igual; os 13 são ponderados pela população.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "31": "<p>Certo. Art. 481, § 11.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "32": "<p>Certo. Art. 481, § 12.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "33": "<p>Certo. Art. 482, caput.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "34": "<p>Certo. Art. 482, I.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "35": "<p>Errado. Os requisitos do inciso II são alternativos (ao menos um).</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "36": "<p>Certo. Art. 482-A.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "37": "<p>Certo. Art. 483.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "38": "<p>Certo. Art. 483, § 1º, III.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>", "39": "<p>Certo. Art. 484.</p><p class='fb-fonte'>Lei Complementar 214/2025 — texto compilado</p>"};
